import{_ as l,l as t,o as r,c as h,v as e,p,x as o,d as s,i as n,S as d}from"./chunks/framework.InCnrqk-.js";const u=JSON.parse('{"title":"Sparrow 对 Rayleigh 判据","description":"","frontmatter":{"title":"Sparrow 对 Rayleigh 判据","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/sparrow-criterion.md","filePath":"litho/sparrow-criterion.md","lastUpdated":1789023840000}'),A={name:"litho/sparrow-criterion.md"};function m(E,a,_,B,c,S){const i=t("Mermaid");return r(),h("div",null,[a[1]||(a[1]=e('<h1 id="sparrow-对-rayleigh-判据" tabindex="-1">Sparrow 对 Rayleigh 判据 <a class="header-anchor" href="#sparrow-对-rayleigh-判据" aria-label="Permalink to &quot;Sparrow 对 Rayleigh 判据&quot;">​</a></h1><div class="epigraph"><p>两点刚可分辨，可以定义为中间还剩一点下凹，也可以定义为中间已经走平。系数不同，物理仍是两只核的重叠。</p><footer>—— Sparrow (1916) 对光谱分辨的定义；Rayleigh 的两针孔习惯读法见 Born &amp; Wolf</footer></div><p><a href="/litho/ctf-otf">上一课</a>给出了 CTF / OTF 的支撑与形状。缺口是：显微镜教材里的「刚可分辨」有不止一种几何，主干<a href="/litho/rayleigh-litho">瑞利课</a>已经把产线式子钉成 \\(k_1\\lambda/\\mathrm{NA}\\)，补层还缺 <strong>Sparrow 与显微镜 Rayleigh 的对照</strong>——以免后课把 0.47、0.61 和 \\(k_1\\) 三个数混成一个。本课不重推产线 CD 公式。Abbe 法与 Hopkins 法的计算顺序留给<a href="/litho/abbe-vs-hopkins">下一课</a>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>非相干两点，像是两只 Airy（或两只 \\(|h|^2\\)）相加。Rayleigh 的习惯说法：一斑的最大值落在另一斑的第一暗环上，中间强度约为峰值的 0.735，看起来刚有鞍。圆孔给出中心距约 \\(0.61\\,\\lambda/\\mathrm{NA}\\)。Sparrow（1916，光谱学）改判据：调节间距，直到合成强度在中点的二阶导数为零——剖面走平、即将出现下凹。同一圆孔、非相干下，间距大约 \\(0.47\\,\\lambda/\\mathrm{NA}\\)。</p><p>缺口不是再画一次 PSF，而是：这两条都是<strong>两点、线性、无胶</strong>的几何，都不是产线 \\(k_1\\)。把 Sparrow 写成「更激进的光刻分辨率」，会假造一条没有照明、没有阈值的工艺。</p><h3 id="相干两点更糟" tabindex="-1">相干两点更糟 <a class="header-anchor" href="#相干两点更糟" aria-label="Permalink to &quot;相干两点更糟&quot;">​</a></h3><p>完全相干、同相两点：场相加再取模方，中间不容易出现鞍，有效分辨比非相干差。反相两点可以出现零，看起来「更好」。光刻掩模的相邻开口相位由照明与物体共同决定，不能套光谱学里的相干两点公式。部分相干落在中间，要用 TCC 算合成强度，不要在 Sparrow 系数上插值冒充 \\(\\sigma\\)。</p><p><span class="marginnote">Rayleigh 自己讨论的是衍射图样可否分开；0.61 来自 \\(J_1\\) 零点，不是他为光刻写的工艺因子。产线把比例改称 \\(k_1\\)，打包照明、掩模与胶，见主干瑞利课。本课只对照两种显微镜/光谱判据。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对给定 PSF，沿连线放两个等权点源，扫间距 \\(d\\)，看合成 \\(I(x)\\)：</p><ul><li>Rayleigh：一峰对齐另一核的指定零点（圆孔 Airy 即第一暗环）。</li><li>Sparrow：\\(\\partial^2 I/\\partial x^2|_{x=0}=0\\)（中点）。</li></ul><p>换孔径切趾、换遮拦、换像差，两个系数都变，因为核变了。因此「Sparrow 常数」不是普适物理常数，只是对那只核的一个数。报判据必须声明：相干还是非相干、圆孔还是实际光瞳。</p><p>光刻要的不是两点鞍，而是阈值等高线是否在规格内、NILS 是否够。两点判据最多用来读「核有多宽」，与<a href="/litho/psf-airy">上一课</a>的光学直径是同一类量。</p>',14)),(r(),p(d,null,{default:o(()=>[n(i,{id:"mermaid-49",class:"mermaid",graph:"flowchart%20TD%0A%20%20TWO%5B%22%E4%B8%A4%E5%8F%AA%20PSF%20%E9%87%8D%E5%8F%A0%22%5D%20--%3E%20RAY%5B%22Rayleigh%EF%BC%9A%E5%B3%B0%E5%AF%B9%E6%9A%97%E7%8E%AF%22%5D%0A%20%20TWO%20--%3E%20SPA%5B%22Sparrow%EF%BC%9A%E4%B8%AD%E7%82%B9%E4%BA%8C%E9%98%B6%E5%AF%BC%E4%B8%BA%E9%9B%B6%22%5D%0A%20%20RAY%20--%3E%20GEO%5B%22%E6%97%A0%E8%83%B6%E5%87%A0%E4%BD%95%E9%97%B4%E8%B7%9D%22%5D%0A%20%20SPA%20--%3E%20GEO%0A%20%20GEO%20--%3E%20K1%5B%22%E4%BA%A7%E7%BA%BF%EF%BC%9Ak1%20%CE%BB%2FNA%EF%BC%88%E4%B8%8D%E5%9C%A8%E6%9C%AC%E8%AF%BE%E9%87%8D%E6%8E%A8%EF%BC%89%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=e('<h3 id="与传递函数的关系" tabindex="-1">与传递函数的关系 <a class="header-anchor" href="#与传递函数的关系" aria-label="Permalink to &quot;与传递函数的关系&quot;">​</a></h3><p>正弦物的 OTF 在某个 \\(f\\) 仍大于零，不保证两个亮点按 Sparrow 可分：一个是周期调制，一个是两点脉冲。CTF/OTF 回答频率还在不在；两点判据回答脉冲对的空域重叠。后课禁戒节距走频率，接触孔走二维核重叠，不要混用判据名字。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>走平（Sparrow）比刚出鞍（Rayleigh）要求两核靠得更近，所以同一只 Airy 下 Sparrow 间距更小。这只说明判据更「乐观」，不说明系统分辨率提高了。胶的阈值可以切在鞍上或切在斜坡上，等效判据随 \\(I_\\mathrm{th}\\) 与 \\(\\gamma\\) 变，这正是 \\(k_1\\) 存在的原因，本课不把它展开成新公式。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>Sparrow 原文针对光谱线；搬到投影光刻只作核宽度的对照。禁止用 0.47 替换产线 CD 式中的 \\(k_1\\)，也禁止把 0.61 叫成「理论 \\(k_1\\)」。矢量成像下两点核随偏振变，判据数字跟着变，定义结构不变。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Rayleigh：峰对暗环，圆孔非相干约 \\(0.61\\,\\lambda/\\mathrm{NA}\\)。</li><li>Sparrow：中点二阶导为零，同条件下间距更小（约 \\(0.47\\,\\lambda/\\mathrm{NA}\\)）。</li><li>两者都是无胶两点几何，不是产线 \\(k_1\\)。</li><li>相干两点不能套非相干系数。</li><li>下一课：同一套核，Abbe 循环对 Hopkins 核。</li><li>出处：Sparrow, <em>Astrophysical Journal</em> (1916)；Born &amp; Wolf；主干瑞利课的 \\(k_1\\) 惯例。</li></ul>',8))])}const b=l(A,[["render",m]]);export{u as __pageData,b as default};
